from collections import Counter


def parse(line):
    parts = line.split()
    return {"ts": parts[0] + " " + parts[1], "level": parts[2], "message": parts[3]}


def parse_all(lines):
    return [parse(line) for line in lines if line.strip()]


def count_levels(lines):
    return dict(Counter(r["level"] for r in parse_all(lines)))


def between(records, start, end):
    return [r for r in records if start <= r["ts"] < end]

