import unittest
from logs import between, parse, parse_all


class Regression(unittest.TestCase):
    def test_parse_fields(self):
        r = parse("2024-01-05 12:00:01 WARN disk almost full")
        self.assertEqual((r["ts"], r["level"]), ("2024-01-05 12:00:01", "WARN"))

    def test_blank_lines_are_skipped(self):
        self.assertEqual(len(parse_all(["", "   ", "2024-01-05 12:00:01 INFO ok"])), 1)

    def test_a_window_can_span_midnight(self):
        recs = [
            {"ts": "2024-01-05 23:59:50", "level": "INFO", "message": "late"},
            {"ts": "2024-01-06 00:00:10", "level": "INFO", "message": "early"},
            {"ts": "2024-01-06 00:05:00", "level": "INFO", "message": "after"},
        ]
        got = between(recs, "2024-01-05 23:59:00", "2024-01-06 00:00:30")
        self.assertEqual([r["message"] for r in got], ["late", "early"])

